import{_ as i,l as o,o as e,c as A,v as t,p as E,x as l,d,i as n,S as s}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"AFM 线宽","description":"","frontmatter":{"title":"AFM 线宽","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/afm-cd.md","filePath":"litho/afm-cd.md","lastUpdated":1789023840000}'),p={name:"litho/afm-cd.md"};function h(M,a,C,D,c,m){const r=o("Mermaid");return e(),A("div",null,[a[1]||(a[1]=t('<h1 id="afm-线宽" tabindex="-1">AFM 线宽 <a class="header-anchor" href="#afm-线宽" aria-label="Permalink to &quot;AFM 线宽&quot;">​</a></h1><div class="epigraph"><p>针尖沿侧壁走一圈，线宽变成可溯源的三维剖面；慢，却能给 SEM 收缩和 OCD 简并一个几何参考。</p><footer>—— 据 CD-AFM 三维线宽计量的公开原理整理</footer></div><p><a href="/litho/ocd-mueller">上一课</a>用穆勒矩阵把偏振变换记全，剖面仍是电磁反演出来的。缺口是一条尽量不靠光学模型、也能看见侧壁的参考：临界尺寸原子力显微镜（CD-AFM）。本课钉 AFM 线宽。套刻标记从<a href="/litho/overlay-marks">下一课</a>另起，不要把针尖当 overlay。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SEM 有收缩与充电；OCD 有模型简并：CD 变胖与侧壁变陡可以走同一条谱。产线需要一台较慢、较局部、但几何意义清楚的尺，把另外两台钉住。CD-AFM 用经过标定的针尖（常为靴形 / flared tip）伸进沟槽，测左右侧壁和顶底宽，给出三维剖面而不是俯视灰度。</p><p>缺口不是再加偏振通道，而是换相互作用：接触/轻敲力学，不是电子，也不是远场光。把它写成「更准的 SEM」，会漏掉针尖卷积与速度；写成可以场内全抽样，又会忽略它慢到只能当参考与热点剖。</p><h3 id="针尖有宽度" tabindex="-1">针尖有宽度 <a class="header-anchor" href="#针尖有宽度" aria-label="Permalink to &quot;针尖有宽度&quot;">​</a></h3><p>靴形针的突出量进入测到的缝宽。针磨损、污染、侧壁粘连都会改有效宽度。计量通称要求用纳米标准样周期校针，再把针宽从缝宽里扣掉。不报针尖状态的 AFM CD，与不报束条件的 SEM CD 是同一类不可比。</p><p><span class="marginnote">AFM 几乎不引发 CAR 那种电子束收缩，但仍可能刮伤软胶、带起碎屑。ADI 胶上的 CD-AFM 要声明是否破坏性、是否只用于校准片。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用途分三档。参考：对一组光栅用 AFM 定顶宽、底宽、侧壁角，去校准 SEM 算法和 OCD 模型。工程：对热点、倒锥嫌疑、倒塌未完全的弯线看真实剖面——上一课穆勒若给出两个解，AFM 拆简并。监控：抽极少点看趋势，不代替 CDU 抽样密度。</p><p>与 SEM/OCD 对照时必须同一图形、同一工艺点：AFM 测的是接触到的几何，SEM 测二次电子边，OCD 测光斑平均。三数不等是常态；要解释差的来源，而不是选一个当「真」然后丢掉另外两个的信息。</p><h3 id="三维-不是再一条顶视-cd" tabindex="-1">三维，不是再一条顶视 CD <a class="header-anchor" href="#三维-不是再一条顶视-cd" aria-label="Permalink to &quot;三维，不是再一条顶视 CD&quot;">​</a></h3><p>侧壁角、沟底圆角、顶圆、线的高，AFM 一次走完。刻蚀偏置课需要的「斜面」，这里是直接量，而不是从顶视猜。深宽比太高、缝太窄，针进不去，AFM 盲——那时只能靠截面 TEM 或 OCD，并承认参考链断了一截。</p>',14)),(e(),E(s,null,{default:l(()=>[n(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20TIP%5B%22%E6%A0%87%E5%AE%9A%E9%9D%B4%E5%BD%A2%E9%92%88%22%5D%20--%3E%20SCAN%5B%22%E6%B2%BF%E4%BE%A7%E5%A3%81%E6%89%AB%E6%8F%8F%22%5D%0A%20%20SCAN%20--%3E%20PR%5B%22%E4%B8%89%E7%BB%B4%E5%89%96%E9%9D%A2%22%5D%0A%20%20PR%20--%3E%20CD%5B%22%E9%A1%B6%E5%AE%BD%20%2F%20%E5%BA%95%E5%AE%BD%20%2F%20%E8%A7%92%22%5D%0A%20%20SEM%5B%22SEM%3A%20%E6%94%B6%E7%BC%A9%E5%85%85%E7%94%B5%22%5D%20--%3E%20CAL%5B%22%E4%BA%92%E6%A0%A1%E5%87%86%22%5D%0A%20%20OCD%5B%22OCD%3A%20%E6%A8%A1%E5%9E%8B%E7%AE%80%E5%B9%B6%22%5D%20--%3E%20CAL%0A%20%20CD%20--%3E%20CAL%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>针与表面力（范德瓦、接触、静电）把悬臂挠度写成高度。靴形针在侧壁上「卡住」的几何允许测到再入或近再入的倒锥，普通针做不到。卷积：真实剖面与针形状的膨胀，反卷积依赖针模型，过度反卷积会造假角。速度慢，是因为每点要接触稳定，且一场里只能走有限条线——这是参考计量的时间预算，不是扫描机 wph。</p><p>对硬掩模和多晶硅，AFM 更稳；对厚 CAR，针污染快。EUV 薄胶可测，但针相对线高变大，相对误差涨。公开计量文献把 CD-AFM 定位为参考环，而不是在线 APC 的主传感器。</p><p><span class="marginnote">不要把 AFM 的纳米数直接写进扫描机剂量闭环。抽样太稀、延迟太大。它校准 SEM/OCD，后两者再进 APC。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编针尖半径的「标准 10 nm」，不把某品牌机型当节点配置。截面 SEM/TEM 是破坏性参考，与 AFM 互补：TEM 看材料衬度，AFM 看表面几何。套刻是位移，不是线宽；下一课标记与衍射套刻，不要用本课的针去量 overlay。</p><p>周期性太差的逻辑二维图形，针轨迹规划困难，AFM 更适合一维栅和测试结构。全芯片热点仍以 SEM 巡检为主。倒锥与倒塌未完全的弯线，AFM 能看见 SEM 顶视当成「桥」或「CD 爆炸」的剖面，这是它相对上一课偏振通道的几何优势。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CD-AFM 给出三维剖面，作 SEM 收缩与 OCD 简并的几何参考。</li><li>针宽、磨损必须进入缝宽校正；慢，不能当场内主计量。</li><li>三法差一截是常态：电子边、光学反演、接触几何各报各的。</li><li>缝太窄针进不去，参考链要接 TEM 或承认盲区。</li><li>AFM 校准 SEM/OCD，后两者再进 APC，不要用针尖跟剂量环。</li><li>倒锥与未完全倒塌的弯线，AFM 能看见顶视 SEM 误判的剖面。</li><li>出处：CD-AFM 三维线宽计量公开原理；与 SEM/OCD 互校准的产线通称。</li></ul>',9))])}const B=i(p,[["render",h]]);export{_ as __pageData,B as default};
